      if (this.session.sheet()?.id === sheet.id) {
        this.assigned.update((list) =>
          [...list.filter((r) => r.user !== saved.user), saved].sort((a, b) => (a.user < b.user ? -1 : a.user > b.user ? 1 : 0)));
      }
    } catch {
      this.roleError.set('The role could not be assigned.');
    } finally {
